<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>Sistem Durumu | İnokskar</title><style>
:root{font-family:Inter,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#102a51;background:#f4f7fb}*{box-sizing:border-box}body{margin:0}.top{background:#102a51;color:white;padding:16px 24px}.top a{color:white;text-decoration:none;font-weight:750}.wrap{width:min(1240px,calc(100% - 36px));margin:28px auto 64px}.head{display:flex;justify-content:space-between;gap:20px;align-items:flex-end;flex-wrap:wrap}.head h1{margin:4px 0 8px;font-size:clamp(2rem,4vw,2.7rem)}.head-actions{display:flex;gap:8px;flex-wrap:wrap}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-top:24px}.card{background:white;border:1px solid #dce6f3;border-radius:15px;padding:19px;box-shadow:0 8px 24px #102a5108}.card h2{font-size:.95rem;margin:0 0 9px;color:#334f6e}.value{font-size:1.55rem;font-weight:850;color:#15375b}.ok{color:#14744d}.warn{color:#a95a00}.wide{grid-column:1/-1}.span-two{grid-column:span 2}.errors pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f7f9fc;padding:12px;border-radius:9px;border:1px solid #e2e8f0}.muted{color:#617791;font-size:.88rem;line-height:1.5}.button{display:inline-flex;align-items:center;justify-content:center;min-height:44px;padding:10px 14px;border:0;border-radius:9px;background:#1455c0;color:white;text-decoration:none;font-weight:800;cursor:pointer}.button.secondary{background:#fff;color:#244b78;border:1px solid #cbd9e9}.audit-shell{margin-top:4px}.audit-toolbar{display:grid;grid-template-columns:minmax(240px,1fr) 220px auto;gap:10px;align-items:end;margin:14px 0}.audit-toolbar label{display:grid;gap:6px;color:#516a86;font-size:.76rem;font-weight:800}.audit-toolbar input,.audit-toolbar select{min-height:42px;border:1px solid #ccd9e8;border-radius:8px;padding:9px 11px;font:inherit;color:#173553;background:#fff}.audit-count{display:flex;align-items:center;justify-content:flex-end;min-height:42px;color:#6b7f97;font-size:.82rem;font-weight:750}.audit-list{display:grid}.audit-row{display:grid;grid-template-columns:150px minmax(170px,.8fr) minmax(190px,1fr) minmax(0,1.4fr);gap:12px;padding:12px 0;border-bottom:1px solid #edf1f6;font-size:.84rem;align-items:start}.audit-row:last-child{border:0}.audit-time{color:#7a8da5}.audit-action{font-weight:800;color:#17395f}.audit-actor{color:#405975;font-weight:700}.audit-detail{color:#60758f;overflow-wrap:anywhere}.audit-kind{display:inline-flex;align-items:center;min-height:24px;padding:3px 8px;margin-top:5px;border-radius:999px;background:#eef3f9;color:#526d8d;font-size:.7rem;font-weight:800}.audit-empty{padding:18px 0;color:#73869d}.health-links{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.health-link{font-size:.82rem;font-weight:800;color:#1455c0;text-decoration:none}.health-link:hover{text-decoration:underline}
@media(max-width:1000px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.span-two{grid-column:span 2}.audit-row{grid-template-columns:135px 1fr 1fr}.audit-detail{grid-column:2/-1}.audit-toolbar{grid-template-columns:1fr 200px}.audit-count{grid-column:1/-1;justify-content:flex-start}}
@media(max-width:640px){.top{padding:13px 14px}.wrap{width:calc(100% - 22px);margin:18px auto 42px}.head{align-items:flex-start;flex-direction:column}.head-actions{display:grid;grid-template-columns:1fr;width:100%}.grid{grid-template-columns:1fr;gap:10px}.span-two,.wide{grid-column:auto}.card{padding:17px;border-radius:13px}.button{width:100%;min-height:50px}.audit-toolbar{grid-template-columns:1fr}.audit-count{grid-column:auto}.audit-row{grid-template-columns:1fr;gap:4px;padding:14px 0}.audit-detail{grid-column:auto}.audit-kind{width:max-content}.value{font-size:1.4rem}}
/* R14.10 — system status visual continuation */
.top{min-height:58px;padding:7px max(14px,calc((100vw - 1380px)/2));display:flex;align-items:center;background:#252b33;border-bottom:1px solid #ffffff12;box-shadow:0 7px 22px #1320331f}
.top a{display:inline-flex;align-items:center;justify-content:center;min-height:38px;padding:0 11px;border:1px solid #ffffff16;border-radius:10px;background:#303944;color:#f4f8fd;font-size:.76rem;font-weight:760}
.top a:hover{background:#394655;color:#fff}
.button{position:relative;overflow:hidden;isolation:isolate;background:linear-gradient(180deg,#2478df,#1557b8);box-shadow:0 8px 18px #1455c024;transition:transform .18s ease,box-shadow .18s ease}
.button.secondary{background:#fff;color:#1756a7;border:1px solid #c7d8ee;box-shadow:0 5px 14px #102a5110}
.button::after{content:"";position:absolute;z-index:2;top:-90%;bottom:-90%;left:-58%;width:28%;pointer-events:none;transform:skewX(-22deg);background:linear-gradient(90deg,transparent,#ffffff24,#ffffffd6,#ffffff24,transparent);transition:left .65s cubic-bezier(.22,.61,.36,1)}
.button:hover::after{left:138%}.button:hover{transform:translateY(-1px)}
#mail-test{background:linear-gradient(180deg,#ff8426,#dc5e0b);box-shadow:0 8px 20px #e86d1730}
.card{box-shadow:0 14px 34px #102a510d}
.grid>.card:nth-child(3n+1){border-top:3px solid #2478df}.grid>.card:nth-child(3n+2){border-top:3px solid #f07c24}.grid>.card:nth-child(3n+3){border-top:3px solid #d83d50}
.errors{border-top-color:#d83d50!important}
@media(max-width:640px){
 .top{min-height:58px;padding:7px 10px}.top a{min-height:36px;padding:0 9px;font-size:.7rem}
 .head-actions{grid-template-columns:1fr 1fr;gap:8px}.head-actions>.secondary{grid-column:1/-1}.head-actions>.button{min-height:48px}
}
