</style><link rel="stylesheet" href="/r123-professional.css"><script src="/r123-security.js" defer></script><link rel="stylesheet" href="/r13-interface.css"><link rel="stylesheet" href="/r13-pages.css?v=r14-10"><script src="/r13-pages.js?v=r14-10" defer></script></head><body><div class="top"><a href="/admin">← Yönetim paneline dön</a></div><main class="wrap"><div class="head"><div><p class="muted">ÜRETİM VE SAĞLIK</p><h1>Sistem durumu</h1><p class="muted">Kur, e-posta, veri, otomatik yedek, güvenlik, işlem günlüğü ve son uygulama hatalarını tek ekranda kontrol edin.</p></div><div class="head-actions"><a class="button secondary" href="/admin/mail">E-posta sağlayıcı</a><button class="button" id="mail-test">Hızlı SMTP testi</button><button class="button" id="refresh">Yenile</button></div></div><section class="grid" id="health"><div class="card">Yükleniyor…</div></section></main><script>
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const fmtDate=v=>{if(!v)return 'Henüz yok';const d=new Date(v);return Number.isNaN(d.getTime())?v:d.toLocaleString('tr-TR')};
const fmtSize=v=>{const n=Number(v||0);if(!n)return '0 MB';return (n/1048576).toLocaleString('tr-TR',{maximumFractionDigits:1})+' MB'};
let auditRows=[];
const auditKind=x=>{const s=String(x.action||'').toLocaleLowerCase('tr-TR');if(s.includes('talep')||x.target?.match(/^[a-f0-9]{32}$/i))return'Talep';if(s.includes('garanti'))return'Garanti';if(s.includes('katalog')||s.includes('ürün')||s.includes('fiyat')||s.includes('kategori'))return'Katalog';if(s.includes('giriş')||s.includes('şifre')||s.includes('kullanıcı')||s.includes('yetki'))return'Güvenlik';if(s.includes('smtp')||s.includes('e-posta')||s.includes('yedek')||s.includes('kur')||s.includes('sistem'))return'Sistem';return'Diğer'};
function renderAudit(){const host=document.getElementById('audit-list');if(!host)return;const q=(document.getElementById('audit-search')?.value||'').trim().toLocaleLowerCase('tr-TR');const kind=document.getElementById('audit-filter')?.value||'all';const rows=auditRows.filter(x=>{const k=auditKind(x);const hay=[x.action,x.actor,x.target,x.detail,k].join(' ').toLocaleLowerCase('tr-TR');return(!q||hay.includes(q))&&(kind==='all'||k===kind)});document.getElementById('audit-count').textContent=`${rows.length} kayıt`;host.innerHTML=rows.length?rows.slice(0,200).map(x=>`<div class="audit-row"><div class="audit-time">${esc(fmtDate(x.created))}</div><div><div class="audit-action">${esc(x.action)}</div><span class="audit-kind">${esc(auditKind(x))}</span></div><div class="audit-actor">${esc(x.actor||'Sistem')}</div><div class="audit-detail">${esc([x.target,x.detail].filter(Boolean).join(' · ')||'—')}</div></div>`).join(''):'<div class="audit-empty">Bu filtrelerle eşleşen işlem kaydı yok.</div>';}
async function load(){const host=document.getElementById('health');try{const [hr,ar]=await Promise.all([fetch('/api/admin/system-health',{cache:'no-store'}),fetch('/api/admin/audit',{cache:'no-store'})]);if(hr.status===401||ar.status===401){location.href='/login';return}const b=await hr.json(),a=await ar.json();if(!hr.ok)throw Error(b.error||'Durum alınamadı');auditRows=a.rows||[];const cards=[['Katalog sürümü',b.revision,''],['Garanti kayıtları',b.warranties,''],['Servis / destek talepleri',b.inquiries,''],['EUR/TL kuru',b.rate?Number(b.rate).toLocaleString('tr-TR',{minimumFractionDigits:4,maximumFractionDigits:4})+' ₺':'Bekleniyor',b.rateStale?'warn':'ok'],['E-posta kuyruğu',b.mail.pending+' bekleyen',b.mail.configured?'ok':'warn'],['Otomatik yedek',b.backup.count+' dosya',b.backup.count?'ok':'warn'],['Giriş güvenliği',b.loginSecurity?.locked?'Geçici kilit':'Normal',b.loginSecurity?.locked?'warn':'ok']];host.innerHTML=cards.map(x=>`<div class="card"><h2>${esc(x[0])}</h2><div class="value ${x[2]}">${esc(x[1])}</div></div>`).join('')+`<div class="card"><h2>Son kur kontrolü</h2><div>${esc(fmtDate(b.lastRate))}</div><p class="muted">${esc(b.rateSource||'')}</p></div><div class="card"><h2>E-posta yapılandırması</h2><div class="${b.mail.configured?'ok':'warn'}">${b.mail.configured?'Hazır':'Sağlayıcı ayarı gerekli'}</div><p class="muted">${esc(b.mail.provider||'')} ${b.mail.fromAddress?'· '+esc(b.mail.fromAddress):''}</p><div class="health-links"><a class="health-link" href="/admin/mail">Sağlayıcı ayarlarını aç →</a></div></div><div class="card"><h2>Son otomatik yedek</h2><div>${esc(fmtDate(b.backup.latest))}</div><p class="muted">${esc(fmtSize(b.backup.latestBytes))}</p></div><div class="card"><h2>Başarısız giriş denemeleri</h2><div>${esc(b.loginSecurity?.failedAttempts??0)}</div><p class="muted">${b.loginSecurity?.locked?'Kilit bitişi: '+esc(fmtDate(b.loginSecurity.lockedUntilUtc)):'Hesap kilitli değil'}</p></div><div class="card wide audit-shell"><div><h2>Yönetim işlem günlüğü</h2><p class="muted">Kim, ne zaman, hangi bölümde ne yaptı bilgisini arayın ve filtreleyin.</p></div><div class="audit-toolbar"><label>İşlemlerde ara<input id="audit-search" type="search" placeholder="Kullanıcı, talep no, işlem veya ayrıntı"></label><label>Kategori<select id="audit-filter"><option value="all">Tümü</option><option>Talep</option><option>Garanti</option><option>Katalog</option><option>Güvenlik</option><option>Sistem</option><option>Diğer</option></select></label><div class="audit-count" id="audit-count"></div></div><div id="audit-list" class="audit-list"></div></div><div class="card wide errors"><h2>Son uygulama hataları</h2>${(b.errors||[]).length?(b.errors||[]).map(e=>`<pre>${esc(e)}</pre>`).join(''):'<p class="muted">Kayıtlı hata yok.</p>'}</div>`;document.getElementById('audit-search').addEventListener('input',renderAudit);document.getElementById('audit-filter').addEventListener('change',renderAudit);renderAudit();}catch(e){host.innerHTML=`<div class="card wide"><strong>Durum alınamadı:</strong> ${esc(e.message)}</div>`;}}
document.getElementById('refresh').onclick=load;document.getElementById('mail-test').onclick=async()=>{const btn=document.getElementById('mail-test');btn.disabled=true;try{const r=await fetch('/api/admin/mail/test',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});const b=await r.json().catch(()=>({}));if(!r.ok)throw Error(b.error||'SMTP testi başarısız');alert('SMTP bağlantısı doğrulandı ve test e-postası gönderildi.');await load();}catch(e){alert(e.message);}finally{btn.disabled=false;}};load();</script></body></html>
""";
}
